using System;using System.IO;using System.Linq;using Musikbox;
class GainIntegration{static void Main(string[] a){var song=MediaMetadata.Read(a[0]);var before=File.ReadAllBytes(song.Source);string result=BatchGain.Analyze(new[]{song},a[1],()=>{});if(!result.Contains("input.mp3"))throw new Exception("Keine Analysezeile");Console.WriteLine("OK echte MP3Gain-Analyse");Directory.CreateDirectory(a[2]);foreach(string mode in new[]{"Track","Album","Undo"}){string path=BatchGain.WriteCopies(new[]{song},a[1],a[2],mode,89,()=>{});if(MediaMetadata.Read(Directory.GetFiles(path,"*.mp3").Single()).Artist!=song.Artist)throw new Exception("Tags beschädigt");Console.WriteLine("OK echte MP3Gain-Verarbeitung "+mode);}if(!File.ReadAllBytes(song.Source).SequenceEqual(before))throw new Exception("Original verändert");Console.WriteLine("OK alle MP3Gain-Vorgänge auf Kopien; Original bytegleich");}}
